    int numVertices = target.getNumVertices();
    int numEdges = target.getNumEdges();
    List<GraphEdge> edges = new ArrayList<>();
    HashMap<Integer,GraphNode> nodeMap = new HashMap<>();

    // Add vertices to the graph
    for (int i = 0; i < numVertices; i++) {
        GraphNode node = new GraphNode(i);
        nodeMap.put(i, node);
        target.addVertex(node);
    }

    // Add edges to the graph
    for (int i = 0; i < numEdges; i++) {
        int source = i / 2;
        int target = i % 2;
        GraphEdge edge = new GraphEdge(nodeMap.get(source), nodeMap.get(target));
        edges.add(edge);
        target.addEdge(edge);
    }

    // Set the result map
    for (int i = 0; i < numVertices; i++) {
        resultMap.put(i, nodeMap.get(i));
    }
}

