public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Get the length of the string
    int length = str.length();

    // Create a new byte array to store the UTF-8 encoded bytes
    byte[] bytes = new byte[length];

    // Encode the string into the byte array
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            bytes[i] = (byte) c;
        } else if (c <= 0x7FF) {
            bytes[i] = (byte) (0xC0 | (c >> 6));
            bytes[i + 1] = (byte) (0x80 | (c & 0x3F));
            i++;
        } else {
            bytes[i] = (byte) (0xE0 | (c >> 12));
            bytes[i + 1] = (byte) (0x80 | ((c >> 6) & 0x3F));
            bytes[i + 2] = (byte) (0x80 | (c & 0x3F));
            i += 2;
        }
    }

    // Write the bytes to the LinkedBuffer
    lb.write(bytes);

    // Return the LinkedBuffer
    return lb;
}

